tegrada","order":33,"period":"6º Período","name":"GESTÃO E ORGANIZAÇÃO DA EDUCAÇÃO BÁSICA","hours":60},{"source":"ped_integrada","order":34,"period":"6º Período","name":"METODOLOGIA DA PESQUISA","hours":60},{"source":"ped_integrada","order":35,"period":"6º Período","name":"ELETIVA","hours":60},{"source":"ped_integrada","order":36,"period":"6º Período","name":"PRÁTICAS PEDAGÓGICAS NO ENSINO MÉDIO","hours":60},{"source":"ped_integrada","order":37,"period":"6º Período","name":"EXTENSÃO INTEGRADA IV","hours":80},{"source":"ped_integrada","order":38,"period":"6º Período","name":"ESTEM- ESTÁGIO SUPERVISIONADO- DOCÊNCIA NO ENSINO MÉDIO","hours":60},{"source":"ped_integrada","order":39,"period":"7º Período","name":"FUNDAMENTOS DA SUPERVISÃO EDUCACIONAL","hours":60},{"source":"ped_integrada","order":40,"period":"7º Período","name":"EDUCAÇÃO PROFISSIONAL E TRABALHO","hours":60},{"source":"ped_integrada","order":41,"period":"7º Período","name":"EDUCAÇÃO QUILOMBOLA, INDÍGENA E NO CAMPO","hours":60},{"source":"ped_integrada","order":42,"period":"7º Período","name":"TCC I","hours":60},{"source":"ped_integrada","order":43,"period":"7º Período","name":"ELETIVA 2","hours":60},{"source":"ped_integrada","order":44,"period":"7º Período","name":"PRÁTICAS PEDAGÓGICAS EM CONTEXTOS NÃO ESCOLARES","hours":60},{"source":"ped_integrada","order":45,"period":"7º Período","name":"ESTOE- ESTÁGIO SUPERVISIONADO- GESTÃO DE ORGANIZAÇÕES ESCOLARES E NÃO-ESCOLARES","hours":80},{"source":"ped_integrada","order":46,"period":"8º Período","name":"FUNDAMENTOS DA INSPEÇÃO ESCOLAR","hours":60},{"source":"ped_integrada","order":47,"period":"8º Período","name":"TCC II","hours":60},{"source":"ped_integrada","order":48,"period":"8º Período","name":"ELETIVA 3","hours":60},{"source":"ped_integrada","order":49,"period":"8º Período","name":"EJA83- PRÁTICAS PEDAGÓGICAS NA EJA","hours":60},{"source":"log_trs","order":1,"period":"1º Período","name":"Fundamentos de Gestão e Logística","hours":60},{"source":"log_trs","order":2,"period":"1º Período","name":"Introdução a Economia","hours":60},{"source":"log_trs","order":3,"period":"1º Período","name":"Matemática Básica","hours":60},{"source":"log_trs","order":4,"period":"1º Período","name":"Gestão de Pessoas","hours":60},{"source":"log_trs","order":5,"period":"1º Período","name":"Planejamento de Marketing","hours":60},{"source":"log_trs","order":6,"period":"1º Período","name":"Metodologia da Pesquisa Científica","hours":60},{"source":"log_trs","order":7,"period":"1º Período","name":"Saúde e Segurança no trabalho","hours":60},{"source":"log_trs","order":8,"period":"1º Período","name":"Ética e Responsabilidade Empresarial","hours":60},{"source":"log_trs","order":9,"period":"2º Período","name":"Sistemas de armazenagem e movimentação de cargas","hours":60},{"source":"log_trs","order":10,"period":"2º Período","name":"Estatística","hours":60},{"source":"log_trs","order":11,"period":"2º Período","name":"Gestão da qualidade","hours":60},{"source":"log_trs","order":12,"period":"2º Período","name":"Planejamento e Controle de Produção Integrado a Logística","hours":60},{"source":"log_trs","order":13,"period":"2º Período","name":"Gestão Sustentável","hours":60},{"source":"log_trs","order":14,"period":"2º Período","name":"Gestão de Projetos","hours":60},{"source":"log_trs","order":15,"period":"2º Período","name":"Empreendedorismo e Inovação","hours":60},{"source":"log_trs","order":16,"period":"2º Período","name":"Optativa 1","hours":60},{"source":"log_trs","order":17,"period":"3º Período","name":"Administração de Materiais","hours":60},{"source":"log_trs","order":18,"period":"3º Período","name":"Gestão da Cadeia de Suprimentos","hours":60},{"source":"log_trs","order":19,"period":"3º Período","name":"Transportes na logística","hours":60},{"source":"log_trs","order":20,"period":"3º Período","name":"Gestão de Custos logísticos","hours":60},{"source":"log_trs","order":21,"period":"3º Período","name":"Matemática Financeira","hours":60},{"source":"log_trs","order":22,"period":"3º Período","name":"Logística Internacional","hours":60},{"source":"log_trs","order":23,"period":"3º Período","name":"Projeto Integrador I","hours":60},{"source":"log_trs","order":24,"period":"3º Período","name":"Projeto de Extensão 1","hours":90},{"source":"log_trs","order":25,"period":"4º Período","name":"Transporte de Passageiros","hours":60},{"source":"log_trs","order":26,"period":"4º Período","name":"Comércio Exterior","hours":60},{"source":"log_trs","order":27,"period":"4º Período","name":"Sistemas de Informação Logístico","hours":60},{"source":"log_trs","order":28,"period":"4º Período","name":"Logística Reversa","hours":60},{"source":"log_trs","order":29,"period":"4º Período","name":"Comportamento Organizacional","hours":60},{"source":"log_trs","order":30,"period":"4º Período","name":"Optativa 2","hours":60},{"source":"log_trs","order":31,"period":"4º Período","name":"Projeto Integrador II","hours":60},{"source":"log_trs","order":32,"period":"4º Período","name":"Projeto de Extensão 2","hours":100}]$dados$::jsonb;

    m record;
    u record;
    c record;
    d record;
    quantidade integer;
    unidade_id_resolvida bigint;
    curso_id_resolvido bigint;
    matriz_id_nova bigint;
    componente_id_resolvido bigint;
    matrizes_inseridas integer := 0;
    componentes_inseridos integer := 0;
    matrizes_antigas integer := 0;
    componentes_antigos integer := 0;
    turmas_antigas integer := 0;
BEGIN
    -- A carga é derivada exclusivamente da planilha indicada no cabeçalho.
    -- Qualquer inconsistência causa EXCEPTION e o PostgreSQL desfaz o bloco inteiro.
    IF to_regclass('public.harpiadb_nucleo_unidade') IS NULL
       OR to_regclass('public.harpiadb_cursos_curso') IS NULL
       OR to_regclass('public.harpiadb_cursos_curso_unidade') IS NULL
       OR to_regclass('public.harpiadb_cursos_matriz_curricular') IS NULL
       OR to_regclass('public.harpiadb_cursos_matriz_unidades') IS NULL
       OR to_regclass('public.harpiadb_cursos_componente_curricular') IS NULL
       OR to_regclass('public.harpiadb_cursos_componente_matriz') IS NULL THEN
        RAISE EXCEPTION 'Schema Harpia esperado não foi encontrado. Nada foi apagado.';
    END IF;

    SELECT count(*) INTO quantidade
      FROM jsonb_to_recordset(matrizes)
           AS x(key text, source text, course text, unit text, name text, turno text);
    IF quantidade <> 29 THEN
        RAISE EXCEPTION 'A fonte deveria conter 29 matrizes por turno, mas contém %. Nada foi apagado.', quantidade;
    END IF;

    IF EXISTS (
        SELECT 1
          FROM jsonb_to_recordset(matrizes)
               AS x(key text, source text, course text, unit text, name text, turno text)
         WHERE x.turno NOT IN ('M', 'T', 'N')
    ) THEN
        RAISE EXCEPTION 'A fonte contém turno inválido. Use somente M, T ou N. Nada foi apagado.';
    END IF;

    IF EXISTS (
        SELECT x.key
          FROM jsonb_to_recordset(matrizes)
               AS x(key text, source text, course text, unit text, name text, turno text)
         GROUP BY x.key
        HAVING count(*) > 1
    ) OR EXISTS (
        SELECT x.course, x.unit, x.name, x.turno
          FROM jsonb_to_recordset(matrizes)
               AS x(key text, source text, course text, unit text, name text, turno text)
         GROUP BY x.course, x.unit, x.name, x.turno
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'A fonte contém matrizes duplicadas. Nada foi apagado.';
    END IF;

    IF EXISTS (
        SELECT 1
          FROM jsonb_to_recordset(matrizes)
               AS m(key text, source text, course text, unit text, name text, turno text)
         WHERE NOT EXISTS (
             SELECT 1
               FROM jsonb_to_recordset(componentes)
                    AS d(source text, "order" integer, period text, name text, hours integer)
              WHERE d.source = m.source
         )
    ) THEN
        RAISE EXCEPTION 'Existe matriz sem disciplinas na fonte. Nada foi apagado.';
    END IF;

    SELECT count(*) INTO quantidade
      FROM jsonb_to_recordset(matrizes)
           AS m(key text, source text, course text, unit text, name text, turno text)
      JOIN jsonb_to_recordset(componentes)
           AS d(source text, "order" integer, period text, name text, hours integer)
        ON d.source = m.source;
    IF quantidade <> 1181 THEN
        RAISE EXCEPTION 'A carga deveria gerar 1181 vínculos de disciplinas, mas gera %. Nada foi apagado.', quantidade;
    END IF;

    IF EXISTS (
        SELECT 1
          FROM jsonb_to_recordset(componentes)
               AS d(source text, "order" integer, period text, name text, hours integer)
         WHERE d.period IS NULL OR btrim(d.period) = ''
            OR d.name IS NULL OR btrim(d.name) = ''
            OR d.hours IS NULL OR d.hours <= 0
    ) THEN
        RAISE EXCEPTION 'A fonte contém disciplina sem período/nome ou com carga horária inválida. Nada foi apagado.';
    END IF;

    -- Valida previamente todas as unidades e todos os cursos. Unidades nunca são criadas.
    -- A busca por nome exato e priorizado elimina a antiga ambiguidade da FMO.
    FOR m IN
        SELECT *
          FROM jsonb_to_recordset(matrizes)
               AS x(key text, source text, course text, unit text, name text, turno text)
    LOOP
        SELECT * INTO u
          FROM jsonb_to_recordset(unidades)
               AS x(key text, siglas jsonb, nomes jsonb)
         WHERE x.key = m.unit;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Chave de unidade % não existe na fonte. Nada foi apagado.', m.unit;
        END IF;

        unidade_id_resolvida := NULL;
        SELECT b.id
          INTO unidade_id_resolvida
          FROM jsonb_array_elements_text(u.nomes) WITH ORDINALITY AS a(valor, prioridade)
          JOIN public.harpiadb_nucleo_unidade b
            ON lower(btrim(b.nome)) = lower(btrim(a.valor))
         ORDER BY prioridade, b.status DESC, b.id
         LIMIT 1;
        IF unidade_id_resolvida IS NULL THEN
            SELECT b.id
              INTO unidade_id_resolvida
              FROM jsonb_array_elements_text(u.siglas) WITH ORDINALITY AS a(valor, prioridade)
              JOIN public.harpiadb_nucleo_unidade b
                ON lower(btrim(b.sigla)) = lower(btrim(a.valor))
             ORDER BY prioridade, b.status DESC, b.id
             LIMIT 1;
        END IF;
        IF unidade_id_resolvida IS NULL THEN
            RAISE EXCEPTION 'Unidade % não encontrada no banco. Nada foi apagado.', m.unit;
        END IF;

        SELECT * INTO c
          FROM jsonb_to_recordset(cursos)
               AS x(key text, nome text, sigla text, siglas jsonb, nomes jsonb)
         WHERE x.key = m.course;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Chave de curso % não existe na fonte. Nada foi apagado.', m.course;
        END IF;

        curso_id_resolvido := NULL;
        SELECT b.id
          INTO curso_id_resolvido
          FROM jsonb_array_elements_text(c.nomes) WITH ORDINALITY AS a(valor, prioridade)
          JOIN public.harpiadb_cursos_curso b
            ON lower(btrim(b.nome)) = lower(btrim(a.valor))
         ORDER BY prioridade, b.id
         LIMIT 1;
        IF curso_id_resolvido IS NULL THEN
            SELECT b.id
              INTO curso_id_resolvido
              FROM jsonb_array_elements_text(c.siglas) WITH ORDINALITY AS a(valor, prioridade)
              JOIN public.harpiadb_cursos_curso b
                ON lower(btrim(b.sigla)) = lower(btrim(a.valor))
             ORDER BY prioridade, b.id
             LIMIT 1;
        END IF;
        IF curso_id_resolvido IS NULL THEN
            INSERT INTO public.harpiadb_cursos_curso(nome, sigla)
            VALUES (c.nome, c.sigla)
            RETURNING id INTO curso_id_resolvido;
        END IF;

        UPDATE public.harpiadb_cursos_curso_unidade
           SET ativo = true
         WHERE curso_id = curso_id_resolvido
           AND unidade_id = unidade_id_resolvida;
        IF NOT FOUND THEN
            INSERT INTO public.harpiadb_cursos_curso_unidade(curso_id, unidade_id, ativo)
            VALUES (curso_id_resolvido, unidade_id_resolvida, true);
        END IF;
    END LOOP;

    -- Compatibilidade com as alterações de turno e disciplina temporária.
    ALTER TABLE public.harpiadb_cursos_matriz_curricular
        ADD COLUMN IF NOT EXISTS turno varchar(1);
    ALTER TABLE public.harpiadb_cursos_componente_matriz
        ADD COLUMN IF NOT EXISTS nome_temporario varchar(255);

    SELECT count(*) INTO matrizes_antigas
      FROM public.harpiadb_cursos_matriz_curricular;
    SELECT count(*) INTO componentes_antigos
      FROM public.harpiadb_cursos_componente_matriz;
    IF to_regclass('public.harpiadb_cursos_turma') IS NOT NULL THEN
        EXECUTE 'SELECT count(*) FROM public.harpiadb_cursos_turma'
           INTO turmas_antigas;
    END IF;

    -- Substituição total: remove dependências na ordem segura e preserva
    -- unidades, cursos, CourseUnit, catálogo de componentes, usuários e alocações.
    IF to_regclass('public.harpiadb_cursos_turma') IS NOT NULL THEN
        EXECUTE 'DELETE FROM public.harpiadb_cursos_turma';
    END IF;
    IF to_regclass('public.harpiadb_cursos_matriz_pre_requisitos') IS NOT NULL THEN
        EXECUTE 'DELETE FROM public.harpiadb_cursos_matriz_pre_requisitos';
    END IF;
    DELETE FROM public.harpiadb_cursos_componente_matriz;
    DELETE FROM public.harpiadb_cursos_matriz_unidades;
    DELETE FROM public.harpiadb_cursos_matriz_curricular;

    -- Os DELETEs acima deixam eventos de FK pendentes na transação, e o
    -- PostgreSQL recusa ALTER TABLE nessa situação (erro 55006). Forçar a
    -- checagem imediata das FKs esvazia a fila antes dos ALTERs abaixo.
    SET CONSTRAINTS ALL IMMEDIATE;

    -- Agora que a tabela está vazia, finaliza a estrutura necessária sem risco
    -- de um valor legado de turno bloquear a substituição.
    ALTER TABLE public.harpiadb_cursos_matriz_curricular
        ALTER COLUMN turno TYPE varchar(1) USING upper(left(btrim(turno), 1));
    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint
         WHERE conrelid = 'public.harpiadb_cursos_matriz_curricular'::regclass
           AND conname = 'harpia_matriz_turno_valido'
    ) THEN
        ALTER TABLE public.harpiadb_cursos_matriz_curricular
            ADD CONSTRAINT harpia_matriz_turno_valido
            CHECK (turno IS NULL OR turno IN ('M', 'T', 'N'));
    END IF;

    UPDATE public.harpiadb_cursos_componente_matriz
       SET nome_temporario = ''
     WHERE nome_temporario IS NULL;
    ALTER TABLE public.harpiadb_cursos_componente_matriz
        ALTER COLUMN nome_temporario SET DEFAULT '',
        ALTER COLUMN nome_temporario SET NOT NULL,
        ALTER COLUMN componente_curricular_id DROP NOT NULL;

    IF to_regclass('public.django_migrations') IS NOT NULL THEN
        INSERT INTO public.django_migrations(app, name, applied)
        SELECT 'courses', '0007_matrixcomponent_disciplina_temporaria', CURRENT_TIMESTAMP
        WHERE NOT EXISTS (
            SELECT 1 FROM public.django_migrations
             WHERE app = 'courses' AND name = '0007_matrixcomponent_disciplina_temporaria'
        );
        INSERT INTO public.django_migrations(app, name, applied)
        SELECT 'courses', '0008_curriculummatrix_turno_constraint', CURRENT_TIMESTAMP
        WHERE NOT EXISTS (
            SELECT 1 FROM public.django_migrations
             WHERE app = 'courses' AND name = '0008_curriculummatrix_turno_constraint'
        );
    END IF;

    FOR m IN
        SELECT *
          FROM jsonb_to_recordset(matrizes)
               AS x(key text, source text, course text, unit text, name text, turno text)
         ORDER BY x.key
    LOOP
        SELECT * INTO u
          FROM jsonb_to_recordset(unidades)
               AS x(key text, siglas jsonb, nomes jsonb)
         WHERE x.key = m.unit;
        unidade_id_resolvida := NULL;
        SELECT b.id
          INTO unidade_id_resolvida
          FROM jsonb_array_elements_text(u.nomes) WITH ORDINALITY AS a(valor, prioridade)
          JOIN public.harpiadb_nucleo_unidade b
            ON lower(btrim(b.nome)) = lower(btrim(a.valor))
         ORDER BY prioridade, b.status DESC, b.id
         LIMIT 1;
        IF unidade_id_resolvida IS NULL THEN
            SELECT b.id
              INTO unidade_id_resolvida
              FROM jsonb_array_elements_text(u.siglas) WITH ORDINALITY AS a(valor, prioridade)
              JOIN public.harpiadb_nucleo_unidade b
                ON lower(btrim(b.sigla)) = lower(btrim(a.valor))
             ORDER BY prioridade, b.status DESC, b.id
             LIMIT 1;
        END IF;

        SELECT * INTO c
          FROM jsonb_to_recordset(cursos)
               AS x(key text, nome text, sigla text, siglas jsonb, nomes jsonb)
         WHERE x.key = m.course;
        curso_id_resolvido := NULL;
        SELECT b.id
          INTO curso_id_resolvido
          FROM jsonb_array_elements_text(c.nomes) WITH ORDINALITY AS a(valor, prioridade)
          JOIN public.harpiadb_cursos_curso b
            ON lower(btrim(b.nome)) = lower(btrim(a.valor))
         ORDER BY prioridade, b.id
         LIMIT 1;
        IF curso_id_resolvido IS NULL THEN
            SELECT b.id
              INTO curso_id_resolvido
              FROM jsonb_array_elements_text(c.siglas) WITH ORDINALITY AS a(valor, prioridade)
              JOIN public.harpiadb_cursos_curso b
                ON lower(btrim(b.sigla)) = lower(btrim(a.valor))
             ORDER BY prioridade, b.id
             LIMIT 1;
        END IF;

        INSERT INTO public.harpiadb_cursos_matriz_curricular(
            curso_id, nome, is_vigente, is_rascunho, criada_em, periodo_letivo, turno
        ) VALUES (
            curso_id_resolvido, m.name, true, false, CURRENT_TIMESTAMP, '2026.2', m.turno
        ) RETURNING id INTO matriz_id_nova;

        INSERT INTO public.harpiadb_cursos_matriz_unidades(curriculummatrix_id, unidade_id)
        VALUES (matriz_id_nova, unidade_id_resolvida);

        FOR d IN
            SELECT *
              FROM jsonb_to_recordset(componentes)
                   AS x(source text, "order" integer, period text, name text, hours integer)
             WHERE x.source = m.source
             ORDER BY x."order"
        LOOP
            componente_id_resolvido := NULL;
            SELECT CASE WHEN count(*) = 1 THEN min(cc.id) END
              INTO componente_id_resolvido
              FROM public.harpiadb_cursos_componente_curricular cc
             WHERE lower(btrim(cc.nome)) = lower(btrim(d.name))
               AND cc.carga_horaria_padrao = d.hours;
            IF componente_id_resolvido IS NULL THEN
                SELECT CASE WHEN count(*) = 1 THEN min(cc.id) END
                  INTO componente_id_resolvido
                  FROM public.harpiadb_cursos_componente_curricular cc
                 WHERE lower(btrim(cc.nome)) = lower(btrim(d.name));
            END IF;

            INSERT INTO public.harpiadb_cursos_componente_matriz(
                matriz_id, componente_curricular_id, nome_temporario, codigo,
                periodo, carga_horaria, creditos, docente_id, compartilhado,
                curso_compartilhado_id, carga_horaria_semanal,
                distribuicao_semanal, status, observacoes
            ) VALUES (
                matriz_id_nova,
                componente_id_resolvido,
                CASE WHEN componente_id_resolvido IS NULL THEN d.name ELSE '' END,
                COALESCE((
                    SELECT cc.codigo
                      FROM public.harpiadb_cursos_componente_curricular cc
                     WHERE cc.id = componente_id_resolvido
                ), ''),
                d.period,
                d.hours,
                (d.hours / 20)::smallint,
                NULL,
                false,
                NULL,
                round(d.hours::numeric / 20, 2),
                '',
                'SEM_PROFESSOR',
                ''
            );
            componentes_inseridos := componentes_inseridos + 1;
        END LOOP;
        matrizes_inseridas := matrizes_inseridas + 1;
    END LOOP;

    IF matrizes_inseridas <> 29 OR componentes_inseridos <> 1181 THEN
        RAISE EXCEPTION 'Falha de contagem: matrizes %, vínculos %. Toda a operação será desfeita.',
            matrizes_inseridas, componentes_inseridos;
    END IF;

    SELECT count(*) INTO quantidade
      FROM public.harpiadb_cursos_matriz_curricular;
    IF quantidade <> 29 THEN
        RAISE EXCEPTION 'O banco terminou com % matrizes, em vez de 29. Toda a operação será desfeita.', quantidade;
    END IF;

    SELECT count(*) INTO quantidade
      FROM public.harpiadb_cursos_componente_matriz;
    IF quantidade <> 1181 THEN
        RAISE EXCEPTION 'O banco terminou com % vínculos, em vez de 1181. Toda a operação será desfeita.', quantidade;
    END IF;

    IF EXISTS (
        SELECT 1
          FROM public.harpiadb_cursos_matriz_curricular m
         WHERE m.turno NOT IN ('M', 'T', 'N') OR m.turno IS NULL
    ) OR EXISTS (
        SELECT 1
          FROM public.harpiadb_cursos_matriz_curricular m
         WHERE (SELECT count(*)
                  FROM public.harpiadb_cursos_matriz_unidades mu
                 WHERE mu.curriculummatrix_id = m.id) <> 1
    ) THEN
        RAISE EXCEPTION 'A validação final de turno/unidade falhou. Toda a operação será desfeita.';
    END IF;

    RAISE NOTICE 'SUCESSO: % matrizes antigas, % vínculos antigos e % turmas antigas removidos.',
        matrizes_antigas, componentes_antigos, turmas_antigas;
    RAISE NOTICE 'SUCESSO: 29 matrizes por turno e 1181 vínculos inseridos a partir da planilha.';
END
$substituir_matrizes$;
